第一个现象 addsubview添加新视图时，顶部被挡住了20 解决办法：
// 设置窗口顶部高度为20，以免被遮掩 CGRect theRect = viewController.view.frame; theRect = CGRectOffset(theRect, 0.0, 20.0); viewController.view.frame = theRect; 第二个现象 在UIPopoverController中添加UITabBarController，UITabBarController底部被盖住20 解决办法： 按照我的理解，是因为多了顶部状态栏（statusBar）的问题，
CGRect theRect = tabBarController.view.frame; float statusBarHeight = [[UIApplication sharedApplication] statusBarFrame].size.height; tabBarController.view.frame = CGRectMake(theRect.origin.x, theRect.origin.y, theRect.size.width, theRect.size.height - statusBarHeight);

* 将文件作为Gmail附件备份到Gmail中 * ver 1.0 * 2008-11-15 zGia! * wuliuqiba@gmail.com PHPMailer: http://phpmailer.codeworxtech.com/ http://sourceforge.net/projects/phpmailer
PHP email transport class featuring file attachments, SMTP servers, CCs, BCCs, HTML messages, word wrap, and more. Sends email via sendmail, PHP mail(), QMail, or with SMTP.
php /** * 将文件作为Gmail附件备份到Gmail中 * ver 1.0 * 2008-11-15 zGia! * wuliuqiba@gmail.com */ error_reporting(E_ALL); //error_reporting(E_STRICT); date_default_timezone_set(&#39;Asia/Shanghai&#39;); //@header(&#39;Content-Type: text/html; charset=utf-8&#39;); include(&#34;class.phpmailer.php&#34;); // ############################################################################## // Gmail标签 // 通过filter，设置邮件自动分拣。比如设置filter： // Matches: to:(xxxxx+book@gmail.com) // Do this: Skip Inbox, Apply label &#34;book&#34; $labels = array( &#34;nolabel&#34; = &#34;&#34;, &#34;book&#34; =&gt; &#34;book&#34;, &#34;backup&#34; =&gt; &#34;backup&#34; ); // 是否将多个附件发送到一个邮件中 $more_attaches_email = false; // 附件 // 不能发送可执行文件或大于 20 MB 的邮件 $attaches = array( &#34;E:\phpmailer.rar&#34;, ); // 发邮件 if ($more_attaches_email) { mailer($labels[&#39;book&#39;], $attaches); } else { foreach ($attaches as $attach) { mailer($labels[&#39;backup&#39;], $attach); } } // ############################################################################## // 传送门 function mailer($label, &amp;$attaches) { unset($mail); $mail =&amp; init_mail($label); send_mail($mail, $attaches); } // ############################################################################## // 发邮件 function send_mail(&amp;$mail, &amp;$attaches) { // 邮件主题，正文 $subject = &#34;&#34;; if(empty($attaches)) { echo &#34;No attach!&#34;; exit; } // 多附件 if(is_array($attaches)) { foreach ($attaches as $attach) { $mail-&gt;AddAttachment($attach); $subject .= &#34;|&#34; . basename($attach); } } // 单附件 else { $mail-&gt;AddAttachment($attaches); $subject .= &#34;|&#34; . basename($attaches); } $subject = preg_replace(&#34;/^\|/i&#34;, &#34;&#34;, $subject); echo &#34;Sending $subject now......\n\t\t&#34;; $mail-&gt;Subject = $subject; $mail-&gt;Body = preg_replace(&#34;/\|/i&#34;, &#34; &#34;, $subject); if(!$mail-&gt;Send()) { echo &#34;Failure: &#34; . $mail-&gt;ErrorInfo; } else { echo &#34;Success, message sent.&#34;; } echo &#34;\n&#34;; } // ############################################################################## // 初始化 PHPMailer function init_mail($label = &#34;&#34;) { // 构造 $mail = new PHPMailer(); // 使用 SMTP $mail-&gt;IsSMTP(); // 激活 SMTP 验证你哦是 $mail-&gt;SMTPAuth = true; // 下面3个配置不明白的，可以查看此链接： // http://mail.google.com/support/bin/answer.py?answer=76147 // 此服务器要求安全连接 $mail-&gt;SMTPSecure = &#34;ssl&#34;; // 使用 Gmail 作为 SMTP 服务器 $mail-&gt;Host = &#34;smtp.gmail.com&#34;; // Gmail 服务器的 SMTP 端口号 $mail-&gt;Port = 465; // ****************** 从这里开始 ************************* // 发送邮件的 Gmail 账户 $mail-&gt;Username = &#34;username@gmail.com&#34;; $mail-&gt;Password = &#34;password&#34;; // 添加回复到 //$mail-&gt;AddReplyTo(&#34;replyto@gmail.com&#34;,&#34;replyto&#34;); // 发信人 $mail-&gt;From = &#34;sender@gmail.com&#34;; $mail-&gt;FromName = &#34;sender&#34;; // 收信人 $mail-&gt;AddAddress(&#34;recipients&#34; . ($label ? &#34;+$label&#34; : &#34;&#34;) . &#34;@gmail.com&#34;, &#34;recipients&#34;); // ****************** 到这里结束，改成你自己的gmail账号 ************************* // 邮件编码 $mail-&gt;CharSet = &#34;utf-8&#34;; // HTML 格式邮件，如果使用文本模式查看的话，所显示的信息 $mail-&gt;AltBody = &#34;To view the message, please use an HTML compatible email viewer!&#34;; // 正文折行 $mail-&gt;WordWrap = 50; // 可以使用某个文件内容作为邮件正文 //$body = $mail-&gt;getFile(&#39;contents.html&#39;); //$body = eregi_replace(&#34;[\]&#34;,&#39;&#39;,$body); //$mail-&gt;MsgHTML($body); // 发送 HTML 格式邮件 $mail-&gt;IsHTML(true); return $mail; }

今天研究了半天终于搞明白UTF-8和Unicode互转。 另：javascript中的escape，把汉字转换后的unicode编码中的数字是16进制的。比如：escape(&ldquo;文&rdquo;) = %u6587，如果在html文件中使用，可以写成 【&amp;# x6587】，或者将6587转换为十进制25991，即【&amp;# 25991】。 第一个： utf8_uri_encode，将UTF-8编码的文字转换为%ae%3d格式， 比如，“中”，解析后，是3字节编码的，依次是228(e4)、184(b8)、173(ad)。 最后输出：%e4%b8%ad
/** * Conver utf-8 words to $hex format string * @author wordpress * @param $utf8_string string to encoded using utf-8 [STRING] * @return string of utf8 encode entities [STRING] * @access public */ function utf8_uri_encode( $utf8_string ) { $unicode = &lsquo;&rsquo;; $values = array(); $num_octets = 1; for ($i = 0; $i &lt; strlen( $utf8_string ); $i++ ) { $value = ord( $utf8_string[ $i ] ); if ( $value &lt; 128 ) { // ASCII $unicode .= chr($value); } else { // 根据第一个字节开头的1的数量,判断当前文字是2字节编码还是3字节编码 // 如果 240=&lt; $value &lt;= 248,则是4字节编码，这里没有考虑，估计也用不上 if ( count( $values ) == 0 ) { $num_octets = ( $value &lt; 224 ) ? 2 : 3; } $values[] = $value; // 当存放当前文字的字节数组等于当前文字的字节数时，则输入，并重置数组 if ( count( $values ) == $num_octets ) { if ($num_octets == 3) { $unicode .= &lsquo;%&rsquo; . dechex($values[0]) . &lsquo;%&rsquo; . dechex($values[1]) . &lsquo;%&rsquo; . dechex($values[2]); } else { $unicode .= &lsquo;%&rsquo; . dechex($values[0]) . &lsquo;%&rsquo; . dechex($values[1]); } $values = array(); $num_octets = 1; } } } return $unicode; }
第二个方法：utf8ToUnicodeEntities，将UTF-8编码的文字转换为&amp;#nnnnn或者&amp;#nnn; n={0..9}的Unicode格式
/** * takes a string of utf-8 encoded characters and converts it to a string of unicode entities * each unicode entitiy has the either the form &amp;#nnnnn; or &amp;#nnn; n={0..9} and can be displayed by utf-8 supporting * browsers. * If the character passed maps as lower ascii it stays as such (a single char) instead of being presented as a unicode entity * @author Ronen Botzer * @param $source string encoded using utf-8 [STRING] * @return string of unicode entities [STRING] * @access public */ function utf8ToUnicodeEntities ($source) { // array used to figure what number to decrement from character order value // according to number of characters used to map unicode to ascii by utf-8 $decrement[4] = 240; // 4字节编码 $decrement[3] = 224; // 3字节编码 $decrement[2] = 192; // 2字节编码 $decrement[1] = 0; // ASCII // the number of bits to shift each charNum by $shift[1][0] = 0; // 0xxxxxxx // 110xxxxx 10xxxxxx $shift[2][0] = 6; // 110xxxxx $shift[2][1] = 0; // 10xxxxxx // 1110xxxx 10xxxxxx 10xxxxxx $shift[3][0] = 12; // 1110xxxx $shift[3][1] = 6; // 10xxxxxx $shift[3][2] = 0; // 10xxxxxx // 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx $shift[4][0] = 18; // 11110xxx $shift[4][1] = 12; // 10xxxxxx $shift[4][2] = 6; // 10xxxxxx $shift[4][3] = 0; // 10xxxxxx $pos = 0; $len = strlen ($source); $encodedString = &#39;&#39;; while ($pos &lt; $len) { $asciiPos = ord (substr ($source, $pos, 1)); // 根据第一个字节开头的1的数量,判断当前文字是2字节编码，还是3字节编码，等等... // 然后根据这个，将第一个文字取出来。 if (($asciiPos &gt;= 240) &amp;&amp; ($asciiPos &lt;= 255)) { // 4 chars representing one unicode character $thisLetter = substr ($source, $pos, 4); $pos += 4; } else if (($asciiPos &gt;= 224) &amp;&amp; ($asciiPos &lt;= 239)) { // 3 chars representing one unicode character $thisLetter = substr ($source, $pos, 3); $pos += 3; } else if (($asciiPos &gt;= 192) &amp;&amp; ($asciiPos &lt;= 223)) { // 2 chars representing one unicode character $thisLetter = substr ($source, $pos, 2); $pos += 2; } else { // 1 char (lower ascii) $thisLetter = substr ($source, $pos, 1); $pos += 1; } // 对每个文字进行处理，比如处理“中” // “中”的长度3。 $thisLen = strlen ($thisLetter); if ($thisLen &gt; 1) { // process the string representing the letter to a unicode entity $thisPos = 0; $decimalCode = 0; while ($thisPos &lt; $thisLen) { // 第一个字节的ASCII值 $thisCharOrd = ord (substr ($thisLetter, $thisPos, 1)); if ($thisPos == 0) { // 比如“中”的第一个字节是11100100，而3字节文字的UTF-8编码的高位要加上11100000即224， // 也就是$decrement[3] $charNum = intval ($thisCharOrd - $decrement[$thisLen]); // 因为放到高位，所以左移12位，$shift[3][0] = 12 // 1110xxxx(第1字节) 10xxxxxx(第2字节) 10xxxxxx(第3字节) $decimalCode += ($charNum &lt;&lt; $shift[$thisLen][$thisPos]); } else { // 第2个和以上的字节的高位都要加上10000000，即128 $charNum = intval ($thisCharOrd - 128); // 将第2个和以上的字节分别左移6位，0位（不移动） $decimalCode += ($charNum &lt;&lt; $shift[$thisLen][$thisPos]); } $thisPos++; } if ($thisLen == 1) { $encodedLetter = &#34;&amp;#&#34;. str_pad($decimalCode, 3, &#34;0&#34;, STR_PAD_LEFT) . &#39;;&#39;; } else { $encodedLetter = &#34;&amp;#&#34;. str_pad($decimalCode, 5, &#34;0&#34;, STR_PAD_LEFT) . &#39;;&#39;; } $encodedString .= $encodedLetter; } else { $encodedString .= $thisLetter; } } return $encodedString; } 相关：UTF-8 and Unicode FAQ

yahoo有1G，Gmail有2G，163.com有1G，共4G。
上次到朋友处帮忙调程序，发现他的机器上没有我常用的工具，搞得我特郁闷。
回到家后，我打开gmail收信，突然想到这个邮箱有1G空间啊，1G啊；当时我就开心起来。
马上用MDaemon架设了一个服务器（偶是ADSL拨号，有IP的），发mail喽&hellip;&hellip;
700M的常用软件放在yahoo的邮箱里
500M的电子文档放在gmail 1里，还在继续增加中&hellip;&hellip;
500M的图片在gmail 2里，还在继续增加中&hellip;&hellip;
准备将163.com的空间用来放小游戏，这个我收集了有800M了。
现在我到哪都不怕了，自己最习惯的工具，最常用的文档，最喜欢的图片，最爱玩的游戏，马上就有。
希望mail提供商不要删除我的空间，阿门！
